import{_ as t,c as n,a4 as o,o as a}from"./chunks/framework.Byzl3YxI.js";const u=JSON.parse('{"title":"Extensions in OpenCUI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/providers/extension.md","filePath":"reference/providers/extension.md","lastUpdated":1745260011000}'),i={name:"reference/providers/extension.md"};function s(r,e,l,c,d,p){return a(),n("div",null,e[0]||(e[0]=[o('<h1 id="extensions-in-opencui" tabindex="-1">Extensions in OpenCUI <a class="header-anchor" href="#extensions-in-opencui" aria-label="Permalink to &quot;Extensions in OpenCUI&quot;">​</a></h1><p>OpenCUI has an open architecture designed to make it easy to add new functionality to chatbots. It achieves this by promoting a clear separation between interface and implementation. We abstract the interface for every built-in functionality that may have multiple implementations, such as channels and support systems. The same approach can be applied to application-level functionalities like payment processing. By defining conversational behavior based on stable interfaces, we can easily reuse the same conversational experience across different implementations.</p><p>On OpenCUI, the interface—and the conversational experience potentially defined on top of it—is called a module, while the implementation of a module is called a provider. If there is only one possible implementation, the module can be configured to include the implementation as well.</p><h3 id="types-of-extensions" tabindex="-1">Types of Extensions <a class="header-anchor" href="#types-of-extensions" aria-label="Permalink to &quot;Types of Extensions&quot;">​</a></h3><p>There are two kinds of extensions:</p><ul><li><strong>External extensions</strong>: Those that the OpenCUI platform does not have access to the source code for and can only be used with privately deployed chatbots.</li><li><strong>Internal extensions</strong>: Those that the OpenCUI platform does have access to the source code for (inside OpenCUI or Framely). Chatbots using Framely extensions cannot be exported for private deployment.</li></ul><h3 id="create-module" tabindex="-1">Create module <a class="header-anchor" href="#create-module" aria-label="Permalink to &quot;Create module&quot;">​</a></h3><p>If the service interface you need doesn&#39;t exist yet, create a new one and describe its schema on the OpenCUI platform. System service interfaces are already created for you—if you want to connect to other channels, you can use them directly, like <code>io.opencui.channel.IChannel</code>.</p><p>To create a service interface:</p><ol><li>Go to one of your orgs, in the project list page, click <strong>Create</strong> on the top right, select module.</li><li>In the <strong>Create</strong> popup window: <ul><li>Enter a label for the service module</li><li>Turn on service toggle, enable service</li><li>No need to add language for interface definitions</li><li>Click <strong>Save</strong></li></ul></li><li>Head to the <strong>Service</strong> page, in the <strong>Functions</strong> section, click <strong>Add</strong> to declare function signatures</li><li>Review your changes and merge them into master</li></ol>',10)]))}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
